def accepted(cap: int, xs: list[int]) -> int:
    """Return how many items of xs are accepted by a bounded queue of capacity cap.

    Items are put in order without blocking. Each successful put counts
    toward the result. The first put that finds the queue full ends the
    loop, and no later items are attempted. Returns 0 when xs is empty or
    cap is 0.
    """
    size = 0
    accepted_count = 0
    for _ in xs:
        if size >= cap:
            break
        size += 1
        accepted_count += 1
    return accepted_count


def test_accepted_stops_when_full() -> None:
    assert accepted(2, [1, 2, 3]) == 2


def test_accepted_all_fit() -> None:
    assert accepted(5, [1, 2]) == 2


def test_accepted_exact_fit() -> None:
    assert accepted(3, [1, 2, 3]) == 3


def test_accepted_single_slot() -> None:
    assert accepted(1, [7, 8]) == 1


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_empty_input() -> None:
    assert accepted(4, []) == 0
